export async function mockEntryJourney({page,origin,width,check,onAction=()=>{},snapshot=async()=>{}}){
 const entry=page.getByRole("region",{name:"Add to the synthetic library"}),library=page.getByRole("region",{name:"Saved synthetic library"});
 let segment="manual entry";
 const click=name=>{onAction(`${segment}: ${name}`);return page.getByRole("button",{name,exact:true}).click();};
 const field=name=>entry.getByLabel(name,{exact:true}),select=(name,value)=>entry.getByLabel(name).selectOption(value),message=text=>entry.getByRole("status").filter({hasText:text}).waitFor();
 const saveWait=title=>entry.getByRole("status").filter({hasText:`Saved entry: ${title}`}).waitFor();
 const filled=async title=>{await field("Entry title").waitFor();await page.waitForFunction(({title})=>[...document.querySelectorAll('input')].some(i=>i.value===title),{title});await entry.getByRole("status").filter({hasText:"Synthetic detail filled automatically"}).waitFor();};
 const mood=async()=>{const input=entry.getByRole("checkbox",{name:"funny",exact:true});if(!await input.isChecked())await input.check();};
 const manual=async(title,type="movie")=>{await click("Start fresh manual draft");await field("Entry title").fill(title);await select("Entry type",type);await field("Entry minutes").fill("25");await field("Entry seconds").fill("0");if(type==="series"||type==="anime"){await select("Entry numbering",type==="series"?"season_episode":"continuous");await entry.getByRole("checkbox",{name:"I confirm this is a typical episode duration",exact:true}).check();}await mood();};
 const load=async()=>{await click("All saved titles");await library.getByRole("status").filter({hasText:"Synthetic library ready."}).waitFor();};
 const details=async title=>{await click(`Details: ${title}`);await library.getByRole("heading",{name:`Title details: ${title}`,exact:true}).waitFor();};
 await page.goto(origin+"/mock");await click("Sign in");await page.getByLabel("Username",{exact:true}).fill("Demo.Owner");await page.getByLabel("Password",{exact:true}).fill("synthetic password");await click("Sign in to demo");await page.getByRole("heading",{name:"Account: Demo.Owner",exact:true}).waitFor();await click("Load groups");await click("Select Synthetic Friday friends");await page.getByRole("heading",{name:"Selected group: Synthetic Friday friends",exact:true}).waitFor();
 for(const type of ["movie","series","anime","youtube"]){const title=`Manual ${type} ${width}`;await manual(title,type);await entry.getByRole("button",{name:"Save entry",exact:true}).press("Enter");await saveWait(title);await load();check(await library.getByRole("button",{name:`Details: ${title}`,exact:true}).count()===1,"four-type save reaches actual one-card library");}
 segment="explicit search/paging/autofill";await click("Start fresh manual draft");await field("Synthetic lookup query").fill("synthetic lessons");await select("Provider fixture outcome","empty");await click("Search or resolve fixture");await entry.getByText("No synthetic matches.",{exact:true}).waitFor();await select("Provider fixture outcome","quota");await field("Entry title").fill("Manual survives failure");await click("Search or resolve fixture");await message("quota reached");check(await field("Entry title").inputValue()==="Manual survives failure","failed lookup retains nonsecret draft");await click("Start fresh manual draft");await select("Provider fixture outcome","normal");await click("Search or resolve fixture");await entry.getByRole("button",{name:"Choose Synthetic video 1",exact:true}).waitFor();check(await field("Entry title").inputValue()==="","search does not silently choose first candidate");segment="ID-shaped title search";await field("Synthetic lookup query").fill("WatchNextQA");check(await entry.getByRole("button",{name:/^Choose /}).count()===0,"query change clears prior candidates");await click("Search or resolve fixture");await entry.getByRole("button",{name:"Choose Synthetic video 2",exact:true}).waitFor();await message("nothing was applied");check(await entry.getByLabel("Lookup input kind").inputValue()==="title" && await entry.getByRole("button",{name:/^Choose /}).count()===2 && await field("Entry title").inputValue()==="" && await entry.getByText(/Applied synthetic source/).count()===0,"explicit Title search with 11-character ID-shaped text lists candidates without automatic fill");segment="explicit search/paging/autofill";await click("Next fixture page");await entry.getByRole("button",{name:"Choose Synthetic video 3",exact:true}).waitFor();await click("Previous fixture page");await click("Choose Synthetic video 1");await filled("Synthetic video 1");check(await entry.getByRole("button",{name:"Replace details",exact:true}).count()===0,"clean result fills without second Apply");await click("Save entry");await message("Select at least one");await mood();await click("Save entry");await saveWait("Synthetic video 1");
 segment="strict link and missing runtime";await select("Lookup input kind","link");await field("Synthetic lookup query").fill("https://youtu.be/SYNTHVID002");await select("Provider fixture outcome","missing-runtime");await click("Search or resolve fixture");await filled("Synthetic video 2");check(await field("Entry minutes").inputValue()==="","missing runtime remains manual");await field("Entry minutes").fill("8");await field("Entry seconds").fill("0");await mood();await click("Save entry");await saveWait("Synthetic video 2");
 segment="dirty Keep/Replace and Kinopoisk";await select("Provider fixture outcome","normal");await field("Synthetic lookup query").fill("SYNTHVID003");await click("Search or resolve fixture");await filled("Synthetic video 3");await mood();await field("Entry title").fill("My previous provider correction");await select("Synthetic lookup source","kinopoisk");await field("Synthetic lookup query").fill("synthetic movie");await click("Search or resolve fixture");await click("Choose Synthetic KP Movie 1");await entry.getByRole("button",{name:"Keep my details",exact:true}).waitFor();await click("Keep my details");check(await field("Entry title").inputValue()==="My previous provider correction","Keep retains dirty fields");await entry.getByText(/Applied synthetic source: youtube/).waitFor();await click("Choose Synthetic KP Movie 1");await click("Replace details");await filled("Synthetic KP Movie 1");check(await entry.getByRole("checkbox",{name:"funny",exact:true}).isChecked(),"replacement preserves manual mood");await entry.getByText(/minutes interpretation/).waitFor();await snapshot(entry);await click("Save entry");await saveWait("Synthetic KP Movie 1");
 segment="episodic manual gate";await click("Choose Synthetic KP Series 2");await filled("Synthetic KP Series 2");check(await field("Entry minutes").inputValue()==="" && await entry.getByLabel("Entry numbering").inputValue()==="none","no inferred typical runtime/numbering");await field("Entry minutes").fill("24");await field("Entry seconds").fill("0");await select("Entry numbering","season_episode");await mood();await click("Save entry");await message("Explicitly confirm");await entry.getByRole("checkbox",{name:"I confirm this is a typical episode duration",exact:true}).check();await click("Save entry");await saveWait("Synthetic KP Series 2");
 segment="typing during await";await click("Start fresh manual draft");await select("Synthetic lookup source","youtube");await select("Lookup input kind","link");await field("Synthetic lookup query").fill("SYNTHVID004");await page.getByLabel("Simulated response").selectOption("slow");await click("Search or resolve fixture");await field("Entry title").fill("Typed during lookup");await entry.getByRole("button",{name:"Keep my details",exact:true}).waitFor();check(await field("Entry title").inputValue()==="Typed during lookup","late detail cannot overwrite typing");check(await field("Entry title").evaluate(input=>document.activeElement===input),"late detail does not steal typing focus");await click("Keep my details");await page.getByLabel("Simulated response").selectOption("ready");
 segment="manual duplicate/archive confirmation";await manual("Together Tonight");await click("Save entry");await entry.getByRole("button",{name:"Confirm shared save",exact:true}).waitFor();await click("Return to entry");check(await field("Entry title").inputValue()==="Together Tonight","cancel keeps draft");await click("Save entry");await click("Confirm shared save");await saveWait("Together Tonight");await load();check(await library.getByRole("button",{name:"Details: Together Tonight",exact:true}).count()===1,"duplicate stays one stable shared record");await manual("Saved for Another Day");await click("Save entry");await click("Confirm shared save");await saveWait("Saved for Another Day");await load();await details("Saved for Another Day");await library.getByText("Stable title: archived-movie",{exact:true}).waitFor();
 segment="review expiry and refresh correction";await click("Start fresh manual draft");await select("Lookup input kind","link");await field("Synthetic lookup query").fill("SYNTHVID005");await click("Search or resolve fixture");await filled("Synthetic video 5");await field("Entry title").fill("My retained draft correction");await click("Advance synthetic time ten minutes");await message("Synthetic time advanced ten minutes");check(await field("Entry title").inputValue()==="My retained draft correction" && await field("Entry minutes").inputValue()==="","expired originals cleared, typed correction retained");await click("Start fresh manual draft");await load();await details("Synthetic video 1");await click("Edit shared metadata");await library.getByLabel("Duration seconds",{exact:true}).fill("1");await click("Save metadata");await library.getByRole("heading",{name:"Title details: Synthetic video 1",exact:true}).waitFor();await click("Refresh synthetic metadata");await library.getByRole("heading",{name:/Title details: Synthetic video 1 \(refresh/}).waitFor();await library.getByText("youtube · Full duration: 10m 1s",{exact:true}).waitFor();await library.getByLabel("Refresh fixture outcome").selectOption("quota");await click("Refresh synthetic metadata");await library.getByRole("status").filter({hasText:"quota reached"}).waitFor();await click("Edit shared metadata");await library.getByLabel("Saved title",{exact:true}).fill("My retained provider title");await click("Save metadata");await click("Confirm identity change");await library.getByRole("heading",{name:"Title details: My retained provider title",exact:true}).waitFor();
 segment="thirty-day clearing";await click("Advance synthetic time thirty-one days");await message("Synthetic time advanced thirty-one days");await load();await details("My retained provider title");await library.getByText("Type unavailable · Full duration: 10m 1s",{exact:true}).waitFor();await library.getByText("Genres: Not recorded",{exact:true}).waitFor();await library.getByText("title: authored",{exact:true}).waitFor();await library.getByText("sourceUrl: unavailable",{exact:true}).waitFor();check(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),"entry/review/expired-detail no horizontal overflow");
}
